INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b8418aec-fae9-4f90-b891-d1c527e99708', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$81. óra: Százalékszámítás$q$, $q$1 egész = 100%, 1% fogalma (századrész), százalék és törtrész kapcsolata.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "91f81bb1-a65d-457e-a159-2798b21ac1fb", "text": "Mit jelent a 1% (egy százalék) fogalma?", "type": "multiple-choice", "options": [{"id": "ae4623a4-5a5f-4f03-8b53-72d4c33f391d", "text": "Az egész mennyiség 1/100-ad részét (századrészét)", "isCorrect": true}, {"id": "73a8b2de-dbfb-4ca3-958e-45e7df3cdd01", "text": "Az egész 1/10-ed részét", "isCorrect": false}, {"id": "e08622fd-3d46-48fa-9931-13635bfa9c74", "text": "100 egészet", "isCorrect": false}, {"id": "6e601d00-b934-4f6e-b3d4-a3ac22a732e7", "text": "Az egész felét", "isCorrect": false}], "timeLimit": 15}, {"id": "bd4a0800-49eb-4948-8f40-d7c5f31ab81e", "text": "Hány százalék felel meg a teljes egésznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "c6e2db87-a53c-4c9b-a1fa-1469a4cc1612", "text": "Hány százalék felel meg a fél (1/2) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "730bd535-9cb6-4f4e-baa3-ea373d095b4c", "text": "Hány százalék felel meg a negyed (1/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "f58ebdc9-ee87-4226-9978-397e15b32ab4", "text": "Hány százalék felel meg a háromnegyed (3/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "51c78e5a-a25d-49d8-8f9f-2c504dcce1ba", "text": "A 10% az egész 1/10-ed részét jelenti.", "type": "true-false", "options": [{"id": "8f1a83cc-ea93-4bdc-bf64-e8150568bbef", "text": "Igaz", "isCorrect": true}, {"id": "ac24af18-96c3-4755-aecb-28053b8cdb0b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d139fa2e-1d56-49d6-9a71-817cb82cbea6", "text": "A 20% az egész 1/5-öd részének felel meg.", "type": "true-false", "options": [{"id": "b175eb53-1bbe-43e0-b9c3-5b81290d607b", "text": "Igaz", "isCorrect": true}, {"id": "7f224c27-6072-4cb1-acf7-ccb866391798", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3a05d05c-0f6b-4c96-b08a-8721a17da173', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$82. óra: A százalékszámítás gyakorlása$q$, $q$Százalékérték kiszámítása következtetéssel (1% kiszámítása) vagy törtrésszel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "67c1d2ba-54fd-4b40-b66a-4345ccf40071", "text": "Mennyi 500 Ft-nak a 10%-a? (500 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "c86a8487-5b7b-4e72-9721-1cd93eb1c147", "text": "Mennyi 500 Ft-nak az 1%-a? (500 / 100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "8291119d-8f86-475b-9e79-e5887a171ca4", "text": "Mennyi 500 Ft-nak a 20%-a? (500 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "afe5b226-e86c-462c-bfac-9c95c4960e28", "text": "Mennyi 800 kg-nak az 50%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "7c90ba41-50cb-42f6-8eb0-05a77477c1ea", "text": "A százalékérték kiszámításához az alapmennyiséget megszorozzuk a százaléklábbal és elosztjuk 100-zal.", "type": "true-false", "options": [{"id": "2fe3d501-f1b6-4bf9-b015-5674ac8b4888", "text": "Igaz", "isCorrect": true}, {"id": "ebd5f4a6-c497-4bd3-b259-38408e39ee78", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "106ab30b-c368-4a7b-ba96-cb9d53716f17", "text": "Mennyi 200 Ft-nak a 25%-a? (200 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "15c6a185-678d-4223-9dc6-574fa13afa28", "text": "Mennyi 1000 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f232a14a-8293-41ec-9f03-865d156775d5', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$83. óra: Feladatmegoldás$q$, $q$Százalékszámítással kapcsolatos hétköznapi szöveges feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "c02a7c17-4ca7-423e-80c8-b64a7ef9b02f", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezmény összege? (10000 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "f9cbe081-b863-4390-a870-a8cf40969279", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezményes ár? (10000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8000"}, {"id": "2d02b34f-85eb-410a-8075-7a7995edc2c7", "text": "Egy iskolában 400 tanuló van. 55%-uk lány. Hány lány jár az iskolába? (400 * 0,55)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "220"}, {"id": "251bb7fa-26aa-43bb-99d8-1983deba839a", "text": "Hány fiú jár az iskolába? (400 - 220)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "632b4201-775e-40ea-b820-1ab8065a9800", "text": "A kedvezményes ár kiszámításához az eredeti árból kivonjuk a kedvezmény értékét.", "type": "true-false", "options": [{"id": "4ba0ac77-4053-456e-809f-694ed51be645", "text": "Igaz", "isCorrect": true}, {"id": "ad19b700-f7c7-454f-aee8-b0755a536fc1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5477991a-71af-4b08-80ab-9dd60c018ebe", "text": "Ha egy ár 10%-kal nő, az új ár az eredeti ár 110%-a lesz.", "type": "true-false", "options": [{"id": "843cc23f-c3a1-4cc2-b0b6-2047ff8fa2d2", "text": "Igaz", "isCorrect": true}, {"id": "6cede01f-a9c5-4b0b-bbb7-6ec849c11772", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "22b269ef-a737-4a68-afed-1008f8e1a002", "text": "Mennyi 50 000 Ft 5%-os kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c98f9d55-5806-4569-8520-ac12ca6d0856', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$84. óra: Feladatmegoldás II.$q$, $q$Összetettebb százalékszámítási feladatok, árleértékelések, drágulások.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "45cd7d74-3381-48c9-b16a-b9d9d227ff40", "text": "Egy 20 000 Ft-os kabát árát 15%-kal felemelték. Hány Ft a drágulás értéke? (20000 * 0,15)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "ad1e254e-c3a4-476e-a2ec-0d4107483d10", "text": "Mennyi a kabát új ára a 15%-os drágulás után? (20000 + 3000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "23000"}, {"id": "43ce343f-895d-4e95-9859-8404f03c34d1", "text": "A 30-as létszámú osztályban a tanulók 10%-a hiányzott. Hány tanuló hiányzott?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "e9a41121-e480-4361-808c-e0fc58777c52", "text": "Hány tanuló volt jelen az osztályban? (30 - 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "7e90d68d-9c42-4ec3-84ab-7551986db5c7", "text": "Ha a 100 Ft-os termék ára 50%-kal csökken, majd a kedvezményes ár 50%-kal nő, az ár visszatér 100 Ft-ra.", "type": "true-false", "options": [{"id": "b6e50982-279a-47e8-a924-9b7e86da4502", "text": "Igaz", "isCorrect": false}, {"id": "9ba8a643-c90c-4e47-b5d5-60d8728e5bd3", "text": "Hamis (50 Ft 50%-os növekedése 75 Ft lesz!)", "isCorrect": true}], "timeLimit": 15}, {"id": "acff7d42-0bb1-4d25-964a-3602a5b6a863", "text": "Mennyi 400 liter 75%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "0f8078e2-9dc4-47fe-b49b-7dc8bd67bdc5", "text": "A százalékszámítás alapvető ismeret a mindennapi pénzügyi tájékozódáshoz.", "type": "true-false", "options": [{"id": "1f311512-bb3d-4f92-8fa6-eb72f59019e6", "text": "Igaz", "isCorrect": true}, {"id": "d7f0438f-0499-4787-8d0f-8848a5a68e6d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b41a607c-4327-4cfe-8cc5-b2ccffbb1a21', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$85. óra: Projektóra$q$, $q$Családi költségvetés készítése megadott keretből, százalékos megoszlások számítása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "42060370-8d45-4b9a-b3c2-789671d39615", "text": "Ha a család havi jövedelme 400 000 Ft, és 30%-ot költenek lakhatásra, hány Ft a lakhatási költség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "5fcb00bf-46ee-4976-aecb-bcb62107d599", "text": "Ha a jövedelem 40%-át élelmiszerre költik, hány Ft megy élelmiszerre? (400000 * 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "d8742f79-5306-4e73-afe2-188dafe4594f", "text": "Hány Ft marad megtakarításra és egyéb kiadásokra? (400000 - 120000 - 160000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "ad5bde88-288c-4a6b-871d-30ac7c48deec", "text": "A családi költségvetés készítésekor a kiadások összege nem haladhatja meg a bevételeket.", "type": "true-false", "options": [{"id": "27b573fb-89d7-40cf-b969-f7b8afa815cd", "text": "Igaz", "isCorrect": true}, {"id": "4d4d547b-e390-424e-8793-035061378f6b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "63137c47-d0c3-44f0-a154-05e5f48fa948", "text": "Hány százalékot tesz ki a megmaradt 120 000 Ft a 400 000 Ft-os jövedelemből?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "85ae779e-044e-4f2f-acdd-d13a0256cf79", "text": "A százalékos megoszlás kördiagramon ábrázolva jól szemlélteti a kiadások arányát.", "type": "true-false", "options": [{"id": "0c7d0d13-549f-4c3a-bf02-6283d24fe8b7", "text": "Igaz", "isCorrect": true}, {"id": "1904739f-df33-4d08-9188-eaff651447db", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ac0cdb8a-7f16-4a5f-a1c7-b96b6ff9c530", "text": "A tudatos pénzügyi tervezés segít elkerülni az eladósodást.", "type": "true-false", "options": [{"id": "e197e996-718d-4c92-8307-a7d6b668a817", "text": "Igaz", "isCorrect": true}, {"id": "7b7311f2-788f-4c4e-8408-d0ea23b803c3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3bcefd1c-c303-41c5-9990-52349bb0c709', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$86. óra: Nyitott mondatok$q$, $q$Lebontogatás (visszafelé gondolkodás) és próbálgatás módszere egyenleteknél.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "1fede69f-1189-4bc0-9d64-4130e487b1a4", "text": "Mit jelent a lebontogatás (visszafelé gondolkodás) módszere?", "type": "multiple-choice", "options": [{"id": "de6c02c1-eb18-4fb5-bbb9-610f0de14f9f", "text": "A végeredményből kiindulva az inverz (ellentétes) műveleteket végezzük el visszafelé", "isCorrect": true}, {"id": "bcbf7377-c375-4b06-a0de-66ed2db11c11", "text": "Visszafelé írjuk le a számokat", "isCorrect": false}, {"id": "bac7a5a6-745a-4db1-941a-6b09d7d85364", "text": "Tippelünk egy számot és feladjuk", "isCorrect": false}, {"id": "8d0cad5e-12d8-4926-b0c2-a6c8bce8a442", "text": "Kivonunk mindent 100-ból", "isCorrect": false}], "timeLimit": 15}, {"id": "c90eaefe-4396-4c30-b8ab-e8cffaabe024", "text": "Melyik szám teszi igazzá: 2 * x + 5 = 17? (17 - 5 = 12, 12 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "67ad5ab4-4282-48ae-a008-0192496b32f7", "text": "Melyik szám teszi igazzá: (y - 4) : 3 = 5? (5 * 3 = 15, 15 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "19"}, {"id": "a11b8c5c-322d-42fb-9e75-a9ac82f70dd1", "text": "Az ellenőrzés során a kapott értéket behelyettesítjük az eredeti nyitott mondatba.", "type": "true-false", "options": [{"id": "99476691-5d08-48d5-a545-f94c4a227618", "text": "Igaz", "isCorrect": true}, {"id": "5d566660-b1f9-429e-967c-e28059b90250", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "258a6f26-dc1d-4cd3-8d67-f1432917a021", "text": "Melyik szám teszi igazzá: 3 * a - 10 = 20?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "7e2ecd16-3c42-4a53-bdbb-3557b60a4596", "text": "A próbálgatásos módszernél rendszerezett táblázatot érdemes vezetni.", "type": "true-false", "options": [{"id": "ac83c299-9a4b-44c8-ba83-e893e81b58c9", "text": "Igaz", "isCorrect": true}, {"id": "d45cc09b-eeaf-47e9-919b-a41cdb844402", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8d52fb86-99ef-493a-93ca-2b2e063c169f", "text": "Melyik szám teszi igazzá: x / 4 + 2 = 7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('90bce308-e7ef-4892-9958-ec6242a171a4', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$87. óra: Feladatmegoldás: Nyitott mondatok$q$, $q$Gyakorlás: lebontogatási módszer alkalmazása egyenletek és egyenlőtlenségek megoldásában.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "f6cbcd91-243f-40c0-82df-2ee79614aa9a", "text": "Melyik szám teszi igazzá: 4 * (x + 2) = 36? (36/4 = 9, 9-2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "d72fac6a-4f43-4961-bf35-0c4cd8bf53d6", "text": "Melyik szám teszi igazzá: 5 * y - 12 = 38? (50/5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e9139dd6-3c7d-4696-a772-62671a610317", "text": "Ha az alaphalmaz a természetes számok (0, 1, 2, ...), hány megoldása van a 2 * x < 6 egyenlőtlenségnek? (x = 0, 1, 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "2c5561a5-cebf-4d4a-a2a5-f05d4d1c1a01", "text": "Az egyenlőtlenségeknek több megoldása is lehet egy megadott alaphalmazon.", "type": "true-false", "options": [{"id": "e5e0329b-5c09-484b-9dc0-3b66c6b537a0", "text": "Igaz", "isCorrect": true}, {"id": "833c20d5-524e-4b01-90ec-c3f5a119b4e4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eadd3544-7f29-4040-8ed2-8acb661f9ba8", "text": "Melyik szám teszi igazzá: (z + 10) / 2 = 15?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "8a968bb6-5c73-4c2a-8a63-c022c14af367", "text": "Ha az egyenletnek nincs megoldása az adott alaphalmazon, az igazsághalmaz az üres halmaz.", "type": "true-false", "options": [{"id": "9806390d-31d2-4de1-a9a9-b1fcba092f75", "text": "Igaz", "isCorrect": true}, {"id": "5ae2d1aa-65d9-41fb-9c70-5c661414ca56", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "671fe2ce-44bf-4eb7-8d16-c71698a75e69", "text": "Melyik szám teszi igazzá: 10 * x - 25 = 75?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1f529dfe-8b59-4801-910a-0cf45a2df913', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$88. óra: Gyakorlóóra$q$, $q$Nyitott mondatok és műveleti sorrend gyakorlása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "d4b8685a-b447-4ddc-8c8e-96bd6da1e782", "text": "Melyik szám teszi igazzá: 3 * x + 7 = 34?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "56487c6f-98a4-4aef-b0d3-f6cb12ddb4de", "text": "Melyik szám teszi igazzá: (x - 5) * 6 = 42?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "da7fa6ac-195c-4aa6-b776-f27d00b14681", "text": "A lebontogatás lépései során az utolsóként elvégzett művelet inverzével kezdjük a számolást.", "type": "true-false", "options": [{"id": "b52406a4-c886-466a-9c3e-5aac6d9a8f2e", "text": "Igaz", "isCorrect": true}, {"id": "caaa6ab5-c232-47e2-b3b7-1468a182f43f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4f554358-2f80-4b84-864d-74da802b06e2", "text": "Mennyi x értéke, ha 50 - 2 * x = 30? (2x = 20)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "00e5e2e3-9d07-4631-91d4-0b64d1c77464", "text": "Mennyi y értéke, ha y / 3 - 4 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "d007677d-690d-4538-b7f7-d04a2128146d", "text": "Az ellenőrzés kihagyása növeli a hibázás kockázatát.", "type": "true-false", "options": [{"id": "2c056f86-590b-4c0f-9292-0eab99628c80", "text": "Igaz", "isCorrect": true}, {"id": "65f6d78b-b900-4f6e-9975-e182a4af6272", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dd3458fc-3c46-40f2-90ba-3cdb2817b411", "text": "Melyik szám teszi igazzá: 8 * a + 4 = 68?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e02b8025-b89c-417f-856e-5d056bff90bc', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$89. óra: Szöveges feladatok$q$, $q$Szöveges feladatok megoldása nyitott mondatok felírásával, ábrakészítéssel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "11328bbd-a071-4a8e-a946-b3c592fdf2d1", "text": "Gondoltam egy számot, megszóroztam 3-mal, hozzáadtam 12-őt és 45-öt kaptam. Mi volt a szám? (3x + 12 = 45 -> 3x = 33)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "e17e9b24-66e0-42e0-b47e-98025a225be1", "text": "Gondoltam egy számot, kivontam belőle 8-at, megszoroztam 4-gyel és 40-et kaptam. Mi volt a szám? ((x-8)*4 = 40 -> x-8 = 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "20eb2383-b6cb-49b9-a2c2-00817470e81e", "text": "Katinak 3-szor annyi matricája van, mint Petinek. Összesen 48 matricájuk van. Hány matricája van Petinek? (x + 3x = 48 -> 4x = 48)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "d56b023f-3df2-414c-a890-71ace920cb3f", "text": "Hány matricája van Katinak? (3 * 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "b2fc2744-27df-4118-9dd8-ba911e52c71f", "text": "A szöveges feladatok megoldásának lépései: Értelmezés -> Adatok/Ismeretlen -> Nyitott mondat -> Számolás -> Ellenőrzés -> Válaszmondat.", "type": "true-false", "options": [{"id": "07681d2a-c5df-456d-a59f-d4f6a78b0cca", "text": "Igaz", "isCorrect": true}, {"id": "2643760a-88a1-47e5-a912-0f3bc1b9bb7b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8ce923c6-05f3-44c2-bc65-637cdeb5fa93", "text": "Ha a feladatban a 'kétszer annyi' kifejezés szerepel, 2-vel való szorzásra gondolunk.", "type": "true-false", "options": [{"id": "4a2e864e-d312-4754-838b-dfa337f539d0", "text": "Igaz", "isCorrect": true}, {"id": "25ca60b8-9d09-45ed-bb9d-5b1a95519280", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "92074928-8602-407e-8469-d384882a3ce9", "text": "Gondoltam egy számot, elosztottam 5-tel, hozzáadtam 7-et és 12-őt kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9d11d970-fa0b-401d-9cda-17f06dd6aafe', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$90. óra: Gyakorlóóra$q$, $q$Matematikai szövegezésű feladatok gyakorlása, ábrakészítés, összefüggések.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "0ae6b0ed-99e4-48e5-b7c9-1b38d7ef9bd3", "text": "Apa 4 évvel idősebb, mint Anya. Életkoruk összege 76 év. Hány éves Anya? (2x + 4 = 76 -> 2x = 72)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "207a0711-b25a-4302-8e66-0bbcb84afdf2", "text": "Hány éves Apa? (36 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "02c5fbbb-2de6-4a91-97ad-19d7c396882b", "text": "Egy téglalap kerülete 40 cm. Hosszabbik oldala 4 cm-rel hosszabb a rövidebbnél. Hány cm a rövidebb oldal? (2*(x + x+4) = 40 -> 4x + 8 = 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "d0ea07c3-402b-403b-b43b-064f351c3637", "text": "Hány cm a hosszabbik oldal? (8 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "c0d3af20-5c81-42fb-a170-84b698449bdf", "text": "A szakaszos ábrázolás nagymértékben segít a szöveges feladatok összefüggéseinek megértésében.", "type": "true-false", "options": [{"id": "fc4694b0-ee0d-4f17-85b6-e0d172b3da73", "text": "Igaz", "isCorrect": true}, {"id": "4852b6c6-d2bd-44bd-bd60-b9d41dd4d6e4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cd9366a9-9e63-4202-a729-445641d22909", "text": "Három egymást követő egész szám összege 45. Mi a legkisebb szám? (x + x+1 + x+2 = 45 -> 3x + 3 = 45)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "1ab829fe-361c-4012-9583-763655c0b6ab", "text": "A válaszmondat felírása kötelező a szöveges feladat végén.", "type": "true-false", "options": [{"id": "6a122fb9-ca06-4d96-9937-144cf3c6388a", "text": "Igaz", "isCorrect": true}, {"id": "3a27a8b0-e0d4-49f1-bd81-c4980369e2b1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;